import { Link } from "react-router-dom";

function Error() {
    return (
        <div className="container">
            <h1>Error</h1>
            <p>Incorrect credentials. Please try again.</p>
            <Link to="/login">Back to Login</Link>
        </div>
    );
}

export default Error;
